-- GenDB engine variant Q11-conjunct_permutation: template q11.sql, kind conjunct_permutation (generated by generate.py; frozen)
SELECT
  ps_partkey,
  SUM(ps_supplycost * ps_availqty) AS value
FROM partsupp, supplier, nation
WHERE
  n_name = $1 AND s_nationkey = n_nationkey AND ps_suppkey = s_suppkey
GROUP BY
  ps_partkey
HAVING
  SUM(ps_supplycost * ps_availqty) > (
    SELECT
      SUM(ps_supplycost * ps_availqty) * $2
    FROM partsupp, supplier, nation
    WHERE
      n_name = $1 AND s_nationkey = n_nationkey AND ps_suppkey = s_suppkey
  )
ORDER BY
  value DESC
